import { useQuery } from '@tanstack/react-query';

/** One downloadable sample upload (generated by `npm run samples:build -w @pi/seed` into /public/samples). */
export interface SampleFile {
  file: string;
  title: string;
  format: string;
  source: string;
  rows?: number;
  currency?: string;
  /** Demo login the file belongs to (purchase-order samples are the held-back quarter of that business). */
  login?: string;
  description: string;
}
export interface SampleManifest {
  generatedFrom?: string;
  holdoutFrom?: string;
  files: SampleFile[];
}

export const sampleUrl = (file: string) => `/samples/${file}`;

/** Static manifest served by the web app; absent in builds without samples (then nothing is shown). */
export function useSampleManifest() {
  return useQuery({
    queryKey: ['sample-manifest'],
    queryFn: async (): Promise<SampleManifest> => {
      const r = await fetch('/samples/manifest.json', { cache: 'no-cache' });
      if (!r.ok) throw new Error(`samples manifest: ${r.status}`);
      return (await r.json()) as SampleManifest;
    },
    staleTime: Infinity,
    retry: false,
  });
}
